def audit_trend_alert_grid(
    snapshots: list | tuple,
    sizes: list | tuple,
    settings: list | tuple,
    thresholds: list | tuple,
    minimums: list | tuple,
    capacity: int = 10,
) -> dict:
    """Grid of batch-alert reports over thresholds and minimums.

    ``snapshots``, ``sizes``, ``settings`` and ``capacity`` share the
    exact contract of :func:`audit_trend_batch_alerts` (every
    ``TypeError`` and ``ValueError`` is inherited verbatim; exceptions
    propagate unchanged). ``thresholds`` and ``minimums`` must each be
    a non-empty list or tuple of strictly increasing non-bool positive
    ints; a wrong container or element type raises ``TypeError``, while
    an empty axis, a non-positive value or a non-increasing pair raises
    ``ValueError``.

    With threshold index ``a`` as the outer axis and minimum index
    ``b`` as the inner axis, :func:`audit_trend_batch_alerts` is called
    exactly once per cell as
    ``audit_trend_batch_alerts(snapshots, sizes, settings, capacity,
    thresholds[a], minimums[b])``; the cell state, stored as
    ``reports[a][b]``, is ``[runs, priority]``, a recursive copy of the
    report's same-named values.

    Adjacent states are compared along two sweeps. The threshold-axis
    sweep visits, for each ``b`` (in ascending order) and then
    ``a = 1..A-1``, ``reports[a-1][b]`` and ``reports[a][b]``; the
    minimum-axis sweep visits, for each ``a`` and then ``b = 1..B-1``,
    ``reports[a][b-1]`` and ``reports[a][b]``. Whenever two adjacent
    states differ, ``[axis, former_coordinate, latter_coordinate,
    fields]`` is recorded: ``axis`` is ``"threshold"`` for the first
    sweep and ``"minimum"`` for the second; the coordinates are the
    ``[a, b]`` indices of the former and latter cell; and ``fields``
    lists, in the order ``runs``, ``priority``, the state positions
    whose values differ.

    ``focus`` counts, for each configuration ``p``, the number of cells
    ``c`` in which ``p`` occurs in the cell state's ``priority``; only
    ``[p, c]`` pairs with ``c > 0`` are kept, ordered by ``(-c, p)``.

    Returns a dict whose keys in order are ``thresholds``,
    ``minimums``, ``reports``, ``changes`` and ``focus``; the first two
    values are converted to lists. Every container is recursively
    copied and JSON-compatible (``None`` values kept, numbers never
    rounded); the inputs are never modified.
    """

    def _validate_axis(name: str, values: list | tuple) -> list:
        if not isinstance(values, (list, tuple)):
            raise TypeError(
                f"{name} must be a list or tuple, got {type(values).__name__}"
            )
        if len(values) == 0:
            raise ValueError(f"{name} must not be empty")
        axis: list = []
        for j, value in enumerate(values):
            if not isinstance(value, int) or isinstance(value, bool):
                raise TypeError(
                    f"{name}[{j}] must be a non-bool int, got "
                    f"{type(value).__name__}"
                )
            if value < 1:
                raise ValueError(f"{name}[{j}] must be >= 1, got {value}")
            if j > 0 and value <= axis[j - 1]:
                raise ValueError(
                    f"{name} must be strictly increasing, got "
                    f"{[*axis, value]!r}"
                )
            axis.append(value)
        return axis

    threshold_values = _validate_axis("thresholds", thresholds)
    minimum_values = _validate_axis("minimums", minimums)

    def _copy(value: object) -> object:
        if isinstance(value, dict):
            return {key: _copy(value[key]) for key in value}
        if isinstance(value, list):
            return [_copy(item) for item in value]
        return value

    a_count = len(threshold_values)
    b_count = len(minimum_values)

    reports: list = [[None] * b_count for _ in range(a_count)]
    for a, threshold in enumerate(threshold_values):
        for b, minimum in enumerate(minimum_values):
            result = audit_trend_batch_alerts(
                snapshots,
                sizes,
                settings,
                capacity,
                threshold,
                minimum,
            )
            reports[a][b] = [_copy(result["runs"]), _copy(result["priority"])]

    state_fields = ("runs", "priority")

    def _changed_fields(former: list, latter: list) -> list:
        return [
            state_fields[k]
            for k in range(2)
            if former[k] != latter[k]
        ]

    changes: list = []
    for b in range(b_count):
        for a in range(1, a_count):
            former = reports[a - 1][b]
            latter = reports[a][b]
            if former != latter:
                changes.append(
                    [
                        "threshold",
                        [a - 1, b],
                        [a, b],
                        _changed_fields(former, latter),
                    ]
                )
    for a in range(a_count):
        for b in range(1, b_count):
            former = reports[a][b - 1]
            latter = reports[a][b]
            if former != latter:
                changes.append(
                    [
                        "minimum",
                        [a, b - 1],
                        [a, b],
                        _changed_fields(former, latter),
                    ]
                )

    p_count = len(settings)
    focus_counts = {p: 0 for p in range(p_count)}
    for a in range(a_count):
        for b in range(b_count):
            for p in reports[a][b][1]:
                focus_counts[p] += 1
    focus = [
        [p, count]
        for p, count in sorted(
            focus_counts.items(), key=lambda item: (-item[1], item[0])
        )
        if count > 0
    ]

    return {
        "thresholds": list(threshold_values),
        "minimums": list(minimum_values),
        "reports": reports,
        "changes": changes,
        "focus": focus,
    }


def receptor_level_quantile(
    H: list[list[float]] | tuple[tuple[float, ...], ...],
    W: list[list[float]] | tuple[tuple[float, ...], ...],
    thresholds: list[float] | tuple[float, ...],
    quantiles: list[float] | tuple[float, ...],
    weights: list[float] | tuple[float, ...] | None = None,
) -> list[list[int]]:
    """Weighted quantiles of the per-receptor health level.

    H: non-empty scenario x receptor matrix of health impacts; both the
        outer container and each row must be a list or tuple, rows must be
        non-empty and share one receptor count; each value finite (negative
        values allowed).
    W: matrix of uncertainties with the same shape as ``H``; each value
        finite and >= 0.
    thresholds: list or tuple of exactly 3 finite, non-negative, strictly
        increasing numbers.
    quantiles: non-empty list or tuple of finite numbers, each in
        ``[0, 1]`` and in non-decreasing order.
    weights: ``None`` (the default) or a K-long list or tuple of finite,
        non-negative entries whose ``fsum`` is positive. With ``None``
        every scenario has weight ``1 / K``; otherwise the weights are
        normalized by their ``fsum``.
    Returns ``Q`` where, with ``sigma = W[k][i]``:

    * ``q[j] = 0.5 * erfc((thresholds[j] - H[k][i]) / (sigma * sqrt(2)))``
      when ``sigma > 0``, otherwise ``1.0`` if ``thresholds[j] <= H[k][i]``
      else ``0.0``;
    * ``p[k][i] = [1 - q0, q0 - q1, q1 - q2, q2]`` holds the probabilities
      of the four health levels for scenario ``k`` at receptor ``i``;
    * ``P[i][r] = fsum(w[k] * p[k][i][r] for k in range(K))`` is the
      weighted probability that receptor ``i`` is at level ``r``;
    * ``Q[m][i]`` is the smallest level ``r`` whose cumulative probability
      ``fsum(P[i][s] for s in range(r + 1))`` is ``>= quantiles[m]``
      (``0`` when ``quantiles[m] == 0``).

    ``Q`` is an M x N list of lists of ints, in ``quantiles`` then
    receptor input order.
    """
    impacts = _validate_matrix("H", H, non_negative=False)
    uncertainties = _validate_matrix("W", W)

    if len(uncertainties) != len(impacts):
        raise ValueError(
            f"H and W must have the same number of scenarios, "
            f"got {len(impacts)} and {len(uncertainties)}"
        )
    n_scenarios = len(impacts)
    n_receptors = len(impacts[0])
    for k, row in enumerate(uncertainties):
        if len(row) != n_receptors:
            raise ValueError(
                f"W[{k}] must have {n_receptors} elements, got {len(row)}"
            )

    if not isinstance(thresholds, (list, tuple)):
        raise TypeError(
            f"thresholds must be a list or tuple, got {type(thresholds).__name__}"
        )
    if len(thresholds) != 3:
        raise ValueError(
            f"thresholds must have exactly 3 elements, got {len(thresholds)}"
        )
    levels = []
    for j, item in enumerate(thresholds):
        if not _is_number(item):
            raise TypeError(
                f"thresholds[{j}] must be an int or float, "
                f"got {type(item).__name__}"
            )
        value = float(item)
        _check_finite(f"thresholds[{j}]", value)
        if value < 0:
            raise ValueError(f"thresholds[{j}] must be >= 0, got {value!r}")
        levels.append(value)
    for j in range(1, 3):
        if not levels[j] > levels[j - 1]:
            raise ValueError(
                f"thresholds must be strictly increasing, got {levels!r}"
            )

    if not isinstance(quantiles, (list, tuple)):
        raise TypeError(
            f"quantiles must be a list or tuple, got {type(quantiles).__name__}"
        )
    if len(quantiles) == 0:
        raise ValueError("quantiles must not be empty")
    qs: list[float] = []
    for m, item in enumerate(quantiles):
        if not _is_number(item):
            raise TypeError(
                f"quantiles[{m}] must be an int or float, "
                f"got {type(item).__name__}"
            )
        value = float(item)
        _check_finite(f"quantiles[{m}]", value)
        if not 0.0 <= value <= 1.0:
            raise ValueError(f"quantiles[{m}] must be in [0, 1], got {value!r}")
        if m > 0 and value < qs[m - 1]:
            raise ValueError(
                f"quantiles must be non-decreasing, got {[*qs, value]!r}"
            )
        qs.append(value)

    if weights is None:
        w = [1.0 / n_scenarios] * n_scenarios
    else:
        if not isinstance(weights, (list, tuple)):
            raise TypeError(
                f"weights must be a list or tuple, got {type(weights).__name__}"
            )
        if len(weights) != n_scenarios:
            raise ValueError(
                f"weights length must equal scenario count {n_scenarios}, "
                f"got {len(weights)}"
            )
        raw = []
        for k, item in enumerate(weights):
            if not _is_number(item):
                raise TypeError(
                    f"weights[{k}] must be an int or float, "
                    f"got {type(item).__name__}"
                )
            value = float(item)
            _check_finite(f"weights[{k}]", value)
            if value < 0:
                raise ValueError(f"weights[{k}] must be >= 0, got {value!r}")
            raw.append(value)
        total_weight = math.fsum(raw)
        if total_weight <= 0:
            raise ValueError(f"weights sum must be > 0, got {total_weight!r}")
        w = [value / total_weight for value in raw]

    per_scenario: list[list[list[float]]] = []
    for k in range(n_scenarios):
        rows: list[list[float]] = []
        for i in range(n_receptors):
            mu = impacts[k][i]
            sigma = uncertainties[k][i]
            q: list[float] = []
            for level in levels:
                if sigma > 0:
                    q.append(0.5 * math.erfc((level - mu) / (sigma * math.sqrt(2))))
                else:
                    q.append(1.0 if level <= mu else 0.0)
            rows.append([1.0 - q[0], q[0] - q[1], q[1] - q[2], q[2]])
        per_scenario.append(rows)

    P = [
        [
            math.fsum(
                w[k] * per_scenario[k][i][r] for k in range(n_scenarios)
            )
            for r in range(4)
        ]
        for i in range(n_receptors)
    ]

    Q: list[list[int]] = []
    for q in qs:
        row: list[int] = []
        for i in range(n_receptors):
            if q == 0.0:
                row.append(0)
            else:
                chosen = 3
                for r in range(4):
                    if math.fsum(P[i][s] for s in range(r + 1)) >= q:
                        chosen = r
                        break
                row.append(chosen)
        Q.append(row)

    return Q


